"""Оркестратор reverse-kit для одной игры.

  python run_game.py --game wol --game-dir "C:/Program Files (x86)/Steam/steamapps/common/Wizard of Legend"
  python run_game.py --game wol --ref-dir "C:/visual projects/wol-ref" --skip-unity     # ref уже выгружен
  python run_game.py --game wol --ref-dir ... --status-only                              # только таблица

Шаги (каждый пропускается, если входы не менялись и выходы на месте; --force STEP|all):
  unity       (B) unity_extract: игра -> ref_dir (src/, data/...)
  index       (A) codeindex (или coverage/fallback_index.py) -> work/index/index.json
  coverage    (C1) auto_coverage -> work/coverage/coverage.csv + coverage.md
  collections (B+C) все коллекции из taxonomy/collections.yaml по реестру -> records/collections
  skeleton    (C2) скелеты по корзинам -> records/systems
  agents      контрольная точка: агенты пишут поведение в records/ (см. AGENT_PLAYBOOK.md)
  render      (C2) records -> work/spec/*.md
  verify      (A) сверка чисел спек с кодом и данными -> work/verify
  to_db       (C2) records -> work/entries.jsonl [+ --db mechanics.db]
  status      work/status.md и status.json: таблица «коллекция / записей / состояние»
Файлы, правленные агентами, повторной генерацией не затираются (records/*/.gen_state.json).
"""
from __future__ import annotations
import argparse, hashlib, json, os, subprocess, sys, time
from pathlib import Path

import yaml

KIT = Path(__file__).resolve().parents[1]
PIPE = KIT / "pipeline"
sys.path[:0] = [str(PIPE), str(KIT / "records"), str(KIT / "coverage")]
import extractors as X  # noqa: E402
from recio import Loader, find_files, is_todo, load_file  # noqa: E402

STEPS = ["unity", "index", "coverage", "collections", "skeleton", "agents", "render", "verify", "to_db", "status"]
STEP_VERSION = {"index": 1, "coverage": 3, "collections": 2, "skeleton": 1, "render": 1, "to_db": 1}


# ------------------------------------------------------------------ отпечатки
def fp_paths(*paths) -> str:
    h = hashlib.sha1()
    for p in paths:
        p = Path(p) if p else None
        if p is None or not p.exists():
            h.update(b"-")
            continue
        if p.is_file():
            s = p.stat()
            h.update(f"{p.name}:{s.st_size}:{s.st_mtime_ns}".encode())
        else:
            n = tot = mx = 0
            for f in p.rglob("*"):
                if f.is_file() and ".gen_state" not in f.name and f.suffix != ".tmp":
                    s = f.stat()
                    n += 1; tot += s.st_size; mx = max(mx, s.st_mtime_ns)
            h.update(f"{p.name}:{n}:{tot}:{mx}".encode())
    return h.hexdigest()[:16]


class Ctx:
    def __init__(self, a):
        self.a = a
        self.game = a.game
        self.work = Path(a.work_dir or KIT / "games" / a.game)
        self.ref = Path(a.ref_dir or self.work / "ref")
        self.records = self.work / "records"
        self.index_json = self.work / "index" / "index.json"
        self.cov_csv = self.work / "coverage" / "coverage.csv"
        self.taxonomy = Path(a.taxonomy or KIT / "coverage" / "taxonomy.yaml")
        ov = KIT / "coverage" / "overrides" / f"{a.game}.yaml"
        self.override = ov if ov.exists() else None
        self.registry_path = Path(a.registry or (PIPE / f"registry.{a.game}.yaml"
                                                 if (PIPE / f"registry.{a.game}.yaml").exists() else PIPE / "collections_registry.yaml"))
        self.collections_yaml = KIT / "taxonomy" / "collections.yaml"
        self.status_path = self.work / "status.json"
        self.st = json.loads(self.status_path.read_text(encoding="utf-8")) if self.status_path.exists() else {"steps": {}, "collections": {}}
        self.work.mkdir(parents=True, exist_ok=True)

    def save(self):
        self.st["game"], self.st["updated"] = self.game, time.strftime("%Y-%m-%d %H:%M:%S")
        self.status_path.write_text(json.dumps(self.st, ensure_ascii=False, indent=1), encoding="utf-8")


def log(m):
    print(m, flush=True)


# ------------------------------------------------------------------ каркас шага
def run_step(ctx: Ctx, name: str, fp: str, outputs_ok, fn):
    a = ctx.a
    forced = name in a.force or "all" in a.force
    prev = ctx.st["steps"].get(name, {})
    fp = f"v{STEP_VERSION.get(name, 0)}:{fp}"
    if not forced and prev.get("fp") == fp and prev.get("state") in ("ok", "external") and outputs_ok():
        log(f"[{name}] пропуск: входы не менялись ({prev.get('note', '')})")
        return prev
    if a.dry_run:
        log(f"[{name}] (dry-run) выполнился бы")
        return {"state": "dry-run"}
    t0 = time.time()
    log(f"[{name}] запуск...")
    try:
        state, note = fn()
    except subprocess.CalledProcessError as e:
        state, note = "error", f"код {e.returncode}"
    except Exception as e:
        state, note = "error", f"{e.__class__.__name__}: {e}"[:300]
    rec = {"state": state, "note": note, "fp": fp if state in ("ok", "external") else "", "seconds": round(time.time() - t0, 1),
           "ts": time.strftime("%Y-%m-%d %H:%M:%S")}
    ctx.st["steps"][name] = rec
    ctx.save()
    log(f"[{name}] {state}: {note} ({rec['seconds']} с)")
    return rec


def sh(cmd, **kw):
    log("    $ " + " ".join(str(c) for c in cmd))
    subprocess.run([str(c) for c in cmd], check=True, **kw)


# ------------------------------------------------------------------ шаги
def step_unity(ctx: Ctx):
    a = ctx.a
    have = (ctx.ref / "src").exists() and (ctx.ref / "data").exists()
    gd = Path(a.game_dir) if a.game_dir else None
    fp = fp_paths(gd / "level0", gd) if gd and gd.exists() and not a.skip_unity else "skip"

    def fn():
        if a.skip_unity or gd is None or not gd.exists():
            if not have:
                raise RuntimeError("нет ref_dir (src/, data/) и нет --game-dir: запусти unity_extract (B) или укажи --ref-dir")
            return "external", f"ref_dir уже есть: {ctx.ref}"
        sh([a.unity_python or sys.executable, "-I", KIT / "unity" / "unity_extract.py", "--game-dir", gd, "--out", ctx.ref])
        return "ok", f"-> {ctx.ref}"
    return run_step(ctx, "unity", fp, lambda: have, fn)


def step_index(ctx: Ctx):
    src = ctx.ref / "src"
    exe = KIT / "codeindex" / "bin" / "Release" / "net9.0" / "codeindex.exe"

    def fn():
        out = ctx.index_json.parent
        if exe.exists() and not ctx.a.index_fallback:
            sh([exe, src, "-o", out, "-q"])
            return "ok", f"codeindex -> {ctx.index_json}"
        sh([sys.executable, KIT / "coverage" / "fallback_index.py", "--src", src, "--out", ctx.index_json])
        return "ok", "fallback_index (regex) — менее точен, чем codeindex"
    return run_step(ctx, "index", fp_paths(src) + str(exe.exists() and not ctx.a.index_fallback), ctx.index_json.exists, fn)


def step_coverage(ctx: Ctx):
    def fn():
        cmd = [sys.executable, KIT / "coverage" / "auto_coverage.py", "--index", ctx.index_json, "--taxonomy", ctx.taxonomy,
               "--out", ctx.cov_csv.parent]
        if ctx.override:
            cmd += ["--override", ctx.override]
        if ctx.a.hand_coverage:
            cmd += ["--hand", ctx.a.hand_coverage]
        sh(cmd)
        return "ok", f"{ctx.cov_csv}"
    fp = fp_paths(ctx.index_json, ctx.taxonomy, ctx.override, ctx.a.hand_coverage, KIT / "coverage" / "auto_coverage.py")
    return run_step(ctx, "coverage", fp, ctx.cov_csv.exists, fn)


def load_ctx_data(ctx: Ctx) -> dict:
    import csv
    from index_io import load_index
    tax = yaml.safe_load(ctx.taxonomy.read_text(encoding="utf-8"))
    coll_y = yaml.safe_load(ctx.collections_yaml.read_text(encoding="utf-8"))
    fam_of = {c["id"]: c for c in coll_y["collections"]}
    reg = yaml.safe_load(ctx.registry_path.read_text(encoding="utf-8"))
    idx, cov = None, {}
    if ctx.index_json.exists() and ctx.cov_csv.exists():
        idx = load_index(ctx.index_json)
        cov = {r["type"]: r for r in csv.DictReader(open(ctx.cov_csv, encoding="utf-8"))}
    return {"game": ctx.game, "ref_dir": ctx.ref, "work_dir": ctx.work, "records_dir": ctx.records, "tax": tax,
            "coll": fam_of, "families": coll_y["families"], "registry": reg["collections"], "defaults": reg["defaults"],
            "idx": idx, "cov_by_type": cov}


def step_collections(ctx: Ctx):
    only = set(ctx.a.only.split(",")) if ctx.a.only else None

    def fn():
        d = load_ctx_data(ctx)
        res = {}
        order = sorted(d["coll"], key=lambda c: (d["coll"][c]["priority"], list(d["coll"]).index(c)))
        for cid in order:
            if only and cid not in only:
                continue
            r = X.run_collection(cid, d["registry"].get(cid, {}), d)
            res[cid] = r
            log(f"    {cid:28s} {r['handler']:15s} {r['state']:9s} {r['note']}")
        ctx.st["collections"].update(res)
        bad = [c for c, r in res.items() if r["state"] in ("error",)]
        return ("ok" if not bad else "error"), f"{len(res)} коллекций" + (f", ошибки: {','.join(bad)}" if bad else "")
    fp = fp_paths(ctx.index_json, ctx.cov_csv, ctx.registry_path, ctx.collections_yaml, ctx.ref / "data",
                  PIPE / "extractors.py", ctx.taxonomy)
    if only:
        fp = "only:" + ",".join(sorted(only)) + str(time.time())
    return run_step(ctx, "collections", fp, (ctx.records / "collections").exists, fn)


def step_skeleton(ctx: Ctx):
    def fn():
        import csv
        from index_io import load_index
        import skeleton as S
        idx = load_index(ctx.index_json)
        cov = list(csv.DictReader(open(ctx.cov_csv, encoding="utf-8")))
        tax = S.load_taxonomy(ctx.taxonomy)
        recs = S.build_records(cov, idx, tax, ctx.game, None, ctx.a.chunk)
        out = ctx.records / "systems"
        c = {"written": 0, "unchanged": 0, "kept": 0}
        for name, rec in recs:
            c[X.emit(out, name, rec, S.HEADER)] += 1
        return "ok", f"{len(recs)} файлов (новых/обновлённых {c['written']}, без изменений {c['unchanged']}, правлены агентами {c['kept']})"
    return run_step(ctx, "skeleton", fp_paths(ctx.cov_csv, ctx.index_json, ctx.taxonomy) + str(ctx.a.chunk),
                    (ctx.records / "systems").exists, fn)


def scan_records(ctx: Ctx) -> list[dict]:
    recs = []
    if ctx.records.exists():
        for p in sorted(ctx.records.rglob("*.yaml")):
            try:
                d = load_file(p)
                d["_rel"] = str(p.relative_to(ctx.records)).replace("\\", "/")
                recs.append(d)
            except Exception:
                pass
    return recs


def filled_stats(rec: dict) -> tuple[int, int]:
    """(заполнено, осталось TODO) по rules/catalog/candidates одного файла."""
    filled = todo = 0
    for r in rec.get("rules", []) or []:
        if is_todo(r.get("behavior")):
            todo += 1
        else:
            filled += 1
    for r in rec.get("catalog", []) or []:
        if is_todo(r.get("own_name")) or is_todo(r.get("behavior", "")):
            todo += 1
        else:
            filled += 1
    todo += len(rec.get("candidates", []) or [])
    return filled, todo


def step_agents(ctx: Ctx):
    recs = scan_records(ctx)
    authored = [r for r in recs if r.get("status") in ("draft", "reviewed") and not (r.get("meta") or {}).get("auto")]
    sk = [r for r in recs if r.get("status") == "skeleton"]
    todo = sum(filled_stats(r)[1] for r in sk)
    if authored:
        note = f"записей от агентов: {len(authored)} файлов; скелетов осталось {len(sk)} (TODO {todo})"
        state = "ok"
    else:
        note = f"ЖДЁМ АГЕНТОВ: {len(sk)} скелетов в {ctx.records} (см. pipeline/AGENT_PLAYBOOK.md), затем перезапусти run_game"
        state = "waiting"
    ctx.st["steps"]["agents"] = {"state": state, "note": note, "ts": time.strftime("%Y-%m-%d %H:%M:%S")}
    ctx.save()
    log(f"[agents] {state}: {note}")
    return ctx.st["steps"]["agents"]


def real_records(ctx: Ctx) -> list[Path]:
    """Файлы записей, пригодные для render/to_db: не skeleton."""
    out = []
    for p in sorted(ctx.records.rglob("*.yaml")) if ctx.records.exists() else []:
        try:
            d = yaml.load(p.read_text(encoding="utf-8"), Loader=Loader) or {}
        except Exception:
            continue
        if d.get("status", "draft") != "skeleton":
            out.append(p)
    return out


def is_auto_file(p: Path) -> bool:
    with p.open(encoding="utf-8") as f:
        return f.readline().startswith("# AUTO-GENERATED")


def step_render(ctx: Ctx):
    files = real_records(ctx)
    authored = [p for p in files if not is_auto_file(p)]
    auto = [p for p in files if is_auto_file(p)]
    spec, spec_auto = ctx.work / "spec", ctx.work / "spec_auto"

    def fn():
        if not files:
            return "skipped", "нет записей вне статуса skeleton"
        n = []
        for grp, out in ((authored, spec), (auto, spec_auto)):   # авто-данные отдельно: verify их не касается
            if grp:
                sh([sys.executable, KIT / "records" / "render.py", "--records", *grp, "--out", out, "--skip-skeleton"])
                n.append(f"{len(list(out.glob('*.md')))} md -> {out.name}")
        return "ok", "; ".join(n)
    return run_step(ctx, "render", fp_paths(*files, KIT / "records" / "render.py"), lambda: bool(files) and (spec.exists() or spec_auto.exists()), fn)


def step_verify(ctx: Ctx):
    spec = ctx.work / "spec"
    manual = Path(ctx.a.spec_dir) if ctx.a.spec_dir else None   # ручная спека игры: отчёт отдельно от рендера
    script = KIT / "verify" / "verify_numbers.py"

    def one(src, out):
        sh([sys.executable, script, "--spec", src, "--index", ctx.index_json, "--data", ctx.ref / "data", "--out-dir", out])

    def fn():
        if not script.exists():
            return "skipped", "verify/verify_numbers.py не найден"
        notes = []
        if list(spec.glob("*.md")):
            one(spec, ctx.work / "verify")
            notes.append(f"рендер -> {ctx.work / 'verify'}")
        if manual:
            if not list(manual.glob("*.md")):
                return "error", f"--spec-dir без .md: {manual}"
            one(manual, ctx.work / "verify_manual")
            notes.append(f"ручная -> {ctx.work / 'verify_manual'}")
        return ("ok", "; ".join(notes)) if notes else ("skipped", "нет отрендеренных спек")
    return run_step(ctx, "verify", fp_paths(spec, manual, ctx.index_json, script),
                    lambda: (ctx.work / "verify").exists() and (not manual or (ctx.work / "verify_manual").exists()), fn)


def step_to_db(ctx: Ctx):
    files = real_records(ctx)
    out = ctx.work / "entries.jsonl"

    def fn():
        if not files:
            return "skipped", "нет записей вне статуса skeleton"
        cmd = [sys.executable, KIT / "records" / "to_db.py", "--records", *files, "--jsonl", out]
        if ctx.a.db:
            cmd += ["--db", ctx.a.db]
        sh(cmd)
        return "ok", f"{out}" + (f" + {ctx.a.db}" if ctx.a.db else "")
    return run_step(ctx, "to_db", fp_paths(*files) + str(ctx.a.db), lambda: out.exists() and not ctx.a.db, fn)


# ------------------------------------------------------------------ статус
def build_status(ctx: Ctx) -> str:
    d = load_ctx_data(ctx)
    recs = scan_records(ctx)
    per = {}
    for r in recs:
        base_coll = r.get("collection")
        buckets: dict[str, list] = {}
        for sec in ("rules", "catalog"):
            for it in r.get(sec, []) or []:
                c = it.get("collection") or base_coll
                if c:
                    buckets.setdefault(c, []).append((sec, it))
        if base_coll and base_coll not in buckets:
            buckets[base_coll] = []
        for c, items in buckets.items():
            p = per.setdefault(c, {"filled": 0, "todo": 0, "files": 0, "auto": 0})
            p["files"] += 1
            for sec, it in items:
                bad = is_todo(it.get("behavior")) if sec == "rules" else (is_todo(it.get("own_name")) or is_todo(it.get("behavior", "")))
                if bad:
                    p["todo"] += 1
                elif (r.get("meta") or {}).get("auto"):
                    p["auto"] += 1
                else:
                    p["filled"] += 1
            if r.get("collection") == c:
                p["todo"] += len(r.get("candidates", []) or [])
    lines = [f"# Статус: {ctx.game}", "", f"Обновлено: {time.strftime('%Y-%m-%d %H:%M')}. Реестр: `{ctx.registry_path.name}`.", "",
             "## Шаги", "", "| Шаг | Состояние | Заметка | с |", "|---|---|---|---|"]
    for s in STEPS[:-1]:
        v = ctx.st["steps"].get(s)
        lines.append(f"| {s} | {v['state'] if v else '-'} | {(v or {}).get('note', '')[:110]} | {(v or {}).get('seconds', '')} |")
    lines += ["", "## Коллекции", "", "| Семья | Коллекция | Авто | P | Обработчик | Записей | TODO | Состояние |", "|---|---|---|---|---|---|---|---|"]
    tally = {}
    rows = []
    for fam in d["families"]:
        for cid in fam["collections"]:
            c = d["coll"][cid]
            h = X.pick_handler(cid, d["registry"].get(cid, {}), c["automation"])
            p = per.get(cid)
            run = ctx.st["collections"].get(cid, {})
            if p and (p["filled"] or p["auto"]) and not p["todo"]:
                state = "done" if p["filled"] else "extracted"
            elif p and (p["filled"] or p["auto"]):
                state = "in_progress"
            elif p and p["todo"]:
                state = "skeleton"
            elif run.get("state"):
                state = run["state"]
            else:
                state = "pending"
            if h == "todo" and state in ("pending", "skeleton"):
                state = "todo"
            n = (p["filled"] + p["auto"]) if p else run.get("entries", 0)
            tally[state] = tally.get(state, 0) + 1
            rows.append({"collection": cid, "family": fam["id"], "automation": c["automation"], "priority": c["priority"],
                         "handler": h, "entries": n, "todo": p["todo"] if p else 0, "state": state, "note": run.get("note", "")})
            lines.append(f"| {fam['id']} | {cid} | {c['automation']} | {c['priority']} | {h} | {n} | {p['todo'] if p else 0} | {state} |")
    lines += ["", "Итого: " + ", ".join(f"{k} {v}" for k, v in sorted(tally.items())) + f" (из {len(rows)}).", ""]
    # системные скелеты
    sysrec = [r for r in recs if r["_rel"].startswith("systems/")]
    if sysrec:
        lines += ["## Системные записи (по корзинам)", "", "| Система | Корзина | Часть | Заполнено | TODO | Статус |", "|---|---|---|---|---|---|"]
        for r in sysrec:
            f, t = filled_stats(r)
            lines.append(f"| {r['system']['id']} {r['system']['slug']} | {(r['system'].get('buckets') or [''])[0]} | "
                         f"{(r.get('meta') or {}).get('part', '1/1')} | {f} | {t} | {r.get('status')} |")
    (ctx.work / "status.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    ctx.st["table"] = rows
    ctx.save()
    return "\n".join(lines[-3:-1] if False else [l for l in lines if l.startswith("Итого")])


def step_status(ctx: Ctx):
    s = build_status(ctx)
    log(f"[status] {s} -> {ctx.work / 'status.md'}")


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--game", required=True, help="slug игры (как в mechanics-db)")
    ap.add_argument("--game-dir", help="папка игры (вход unity_extract)")
    ap.add_argument("--ref-dir", help="папка выгрузки (src/, data/); по умолчанию games/<slug>/ref")
    ap.add_argument("--work-dir", help="рабочая папка игры; по умолчанию games/<slug>")
    ap.add_argument("--skip-unity", action="store_true", help="не запускать unity_extract (ref уже есть)")
    ap.add_argument("--unity-python", help="python для unity_extract (его venv)")
    ap.add_argument("--taxonomy"); ap.add_argument("--registry")
    ap.add_argument("--hand-coverage", help="ручной coverage.csv для оценки согласия")
    ap.add_argument("--index-fallback", action="store_true", help="использовать regex-индекс вместо codeindex")
    ap.add_argument("--steps", default=",".join(STEPS), help="подмножество шагов через запятую")
    ap.add_argument("--only", help="только эти коллекции (через запятую)")
    ap.add_argument("--force", nargs="*", default=[], help="шаги, которые выполнить заново, или all")
    ap.add_argument("--chunk", type=int, default=30, help="типов на файл скелета")
    ap.add_argument("--db", help="mechanics.db для прямой вставки (иначе только JSONL)")
    ap.add_argument("--spec-dir", help="ручная спека игры (.md): verify проверяет и её, отчёт в work/verify_manual")
    ap.add_argument("--status-only", action="store_true")
    ap.add_argument("--dry-run", action="store_true")
    a = ap.parse_args()
    ctx = Ctx(a)
    steps = ["status"] if a.status_only else [s for s in a.steps.split(",") if s in STEPS]
    fns = {"unity": step_unity, "index": step_index, "coverage": step_coverage, "collections": step_collections,
           "skeleton": step_skeleton, "agents": step_agents, "render": step_render, "verify": step_verify,
           "to_db": step_to_db, "status": step_status}
    for s in steps:
        r = fns[s](ctx)
        if isinstance(r, dict) and r.get("state") == "error" and s in ("unity", "index", "coverage"):
            log(f"[{s}] критическая ошибка — дальше нельзя")
            step_status(ctx) if s != "status" else None
            sys.exit(2)
    log(f"готово. Статус: {ctx.work / 'status.md'}")


if __name__ == "__main__":
    main()
