"""Обработчики коллекций для run_game.py (реестр: collections_registry.yaml).

Каждый обработчик пишет записи (records/*.yaml в формате reverse-kit-record/1) и возвращает
{"state", "entries", "files", "note"}. Данные игры только читаются. Автоизвлечённые строки получают
НЕЙТРАЛЬНЫЕ имена (own_name = «<вид> NNNN»); идентификаторы референса лежат только в source_ref.
Тексты и байты ассетов в выход не копируются (len_cols / drop / dir_inventory).
"""
from __future__ import annotations
import ast, csv, fnmatch, hashlib, json, operator, re, sys
from pathlib import Path

import yaml

KIT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(KIT / "records"))
sys.path.insert(0, str(KIT / "coverage"))
from skeleton import dump_yaml, type_candidate  # noqa: E402

AUTO_NOTE = "Автоизвлечено из данных игры; поведение не описано — числа в numbers."
HEADER_AUTO = "# AUTO-GENERATED: сгенерировано pipeline/extractors.py; руками не править (перезапишется при изменении входов).\n"
HEADER_SKEL = ("# СКЕЛЕТ коллекции: заполняют агенты (pipeline/AGENT_PLAYBOOK.md). Clean-room: свои слова и имена,\n"
               "# идентификаторы референса — только в source_refs/source_ref. Готово: нет TODO и candidates, status: draft.\n")


# ------------------------------------------------------------------ защита правок агентов
def write_protected(path: Path, text: str, state_file: Path) -> str:
    """Записать text; не затирать файл, изменённый после генерации. -> written|unchanged|kept"""
    st = json.loads(state_file.read_text(encoding="utf-8")) if state_file.exists() else {}
    sha = hashlib.sha1(text.encode("utf-8")).hexdigest()
    key = path.name
    if path.exists():
        cur = hashlib.sha1(path.read_bytes()).hexdigest()
        if cur == sha:
            st[key] = sha
            res = "unchanged"
        elif st.get(key) == cur:          # файл как при прошлой генерации -> можно обновить
            path.write_text(text, encoding="utf-8")
            st[key] = sha
            res = "written"
        else:
            return "kept"                 # правили руками/агент
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        st[key] = sha
        res = "written"
    state_file.parent.mkdir(parents=True, exist_ok=True)
    state_file.write_text(json.dumps(st, indent=1), encoding="utf-8")
    return res


def emit(out_dir: Path, name: str, rec: dict, header: str) -> str:
    tmp = out_dir / ("." + name + ".tmp")
    dump_yaml(rec, tmp, header)
    text = tmp.read_text(encoding="utf-8")
    tmp.unlink()
    return write_protected(out_dir / name, text, out_dir / ".gen_state.json")


# ------------------------------------------------------------------ чтение данных
def read_csv(path: Path) -> list[dict]:
    raw = path.read_text(encoding="utf-8-sig", errors="replace")
    first = raw.split("\n", 1)[0]
    delim = max([",", "|", ";", "\t"], key=first.count)
    return list(csv.DictReader(raw.splitlines(), delimiter=delim))


def read_json_rows(path: Path) -> list[dict]:
    raw = path.read_text(encoding="utf-8-sig", errors="replace")
    try:
        d = json.loads(raw)
    except json.JSONDecodeError:
        dec, i, d = json.JSONDecoder(), 0, []          # NDJSON или объекты через произвольный разделитель
        while True:
            i = raw.find("{", i)
            if i < 0:
                break
            try:
                o, i = dec.raw_decode(raw, i)
                d.append(o)
            except json.JSONDecodeError:
                i += 1
    if isinstance(d, dict):
        lists = [v for v in d.values() if isinstance(v, list) and v and isinstance(v[0], dict)]
        d = lists[0] if len(lists) == 1 else ([{"key": k, **v} for k, v in d.items() if isinstance(v, dict)]
                                              or [d])
    return [x for x in d if isinstance(x, dict)]


def num(x):
    if isinstance(x, bool):
        return None
    if isinstance(x, (int, float)):
        return x
    try:
        f = float(str(x).strip())
        return int(f) if f.is_integer() and "." not in str(x) and "e" not in str(x).lower() else round(f, 6)
    except (TypeError, ValueError):
        return None


_OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}


def safe_eval(expr: str, env: dict):
    def ev(n):
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.BinOp) and type(n.op) in _OPS:
            return _OPS[type(n.op)](ev(n.left), ev(n.right))
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.Name) and env.get(n.id) is not None:
            return env[n.id]
        raise ValueError(n)
    try:
        return ev(ast.parse(expr, mode="eval"))
    except (ValueError, ZeroDivisionError, SyntaxError):
        return None


# ------------------------------------------------------------------ запись рядов каталога
def rows_to_records(ctx: dict, cid: str, cfg: dict, rows: list[dict], kind: str, src: str) -> dict:
    d = ctx["defaults"]
    sid = cfg["system"]
    sysd = ctx["tax"]["systems"][sid]
    per = d["csv_rows_per_file"]
    cap = d["csv_max_rows"]
    total = len(rows)
    rows = rows[:cap]
    out_dir: Path = ctx["records_dir"] / "collections"
    # старые части могли остаться от прошлого запуска
    for old in out_dir.glob(f"c-{cid}*.yaml"):
        if old.name != ".gen_state.json":
            old.unlink()
    parts = [rows[i:i + per] for i in range(0, len(rows), per)] or [[]]
    n = 0
    written = 0
    for pi, part in enumerate(parts, 1):
        cat = []
        for r in part:
            n += 1
            row = {"id": f"C-{sid}-{cid}-{n:04d}", "kind": kind, "own_name": f"{kind} {n:04d}",
                   "numbers": r["numbers"], "behavior": AUTO_NOTE, "source_ref": f"{src}: {r['key']}"}
            if r.get("tags"):
                row["tags"] = r["tags"]
            cat.append(row)
        rec = {"schema": "reverse-kit-record/1", "game": ctx["game"], "status": "draft", "collection": cid,
               "system": {"id": sid, "slug": sysd["slug"], "title": sysd["title"]},
               "goal": f"Коллекция «{ctx['coll'][cid]['title_ru']}»: автоизвлечение из данных игры.",
               "rules": [], "catalog": cat, "open_questions": [], "acceptance": [],
               "meta": {"auto": True, "source": src, "rows_total": total, "rows_written": len(rows),
                        "part": f"{pi}/{len(parts)}"}}
        name = f"c-{cid}" + (f".part{pi:02d}" if len(parts) > 1 else "") + ".yaml"
        res = emit(out_dir, name, rec, HEADER_AUTO)
        written += res == "written"
    note = f"{total} строк" + (f" (записано {cap})" if total > cap else "")
    return {"state": "extracted" if total else "empty", "entries": len(rows), "files": len(parts), "note": note}


def h_csv_rows(cid, cfg, ctx):
    ref: Path = ctx["ref_dir"]
    rows_in, srcs = [], []
    for f in cfg.get("files", []):
        p = ref / f
        if p.exists():
            rows_in += [(f, r) for r in read_csv(p)]
            srcs.append(f)
    if not rows_in:
        return {"state": "blocked", "entries": 0, "files": 0, "note": f"нет входа: {cfg.get('files')}"}
    where = cfg.get("where") or {}
    out = []
    for i, (f, r) in enumerate(rows_in, 1):
        if any(str(r.get(k, "")).lower() not in [str(x).lower() for x in v] for k, v in where.items()):
            continue
        nums = {}
        if cfg.get("len_cols"):
            for k, v in r.items():
                nums[f"{k}_len"] = len(v or "")
        for k in cfg.get("numbers", []):
            v = num(r.get(k))
            if v is not None:
                nums[k] = v
        for k, ex in (cfg.get("derive") or {}).items():
            v = safe_eval(ex, {kk: num(vv) for kk, vv in r.items()})
            if v is not None:
                nums[k] = round(v, 6)
        if not nums:
            continue
        tags = []
        for k in cfg.get("tags", []):
            v = (r.get(k) or "").strip()
            if v and len(v) <= 24:
                tags.append(f"{k}={v}")
        key = " / ".join(str(r.get(k, "")) for k in cfg.get("key", []) if r.get(k)) or f"#{i}"
        out.append({"key": key[:120], "numbers": nums, "tags": tags})
    return rows_to_records(ctx, cid, cfg, out, cfg["kind"], ",".join(srcs))


def h_json_tree(cid, cfg, ctx):
    ref: Path = ctx["ref_dir"]
    out, srcs = [], []
    for f in cfg.get("files", []):
        p = ref / f
        if not p.exists():
            continue
        srcs.append(f)
        for i, r in enumerate(read_json_rows(p), 1):
            nums = {}
            for k, v in r.items():
                if k in cfg.get("key", []):
                    continue
                nv = num(v)
                if nv is not None:
                    nums[k] = nv
                elif isinstance(v, list) and v and all(num(x) is not None for x in v) and len(v) <= 12:
                    nums[k] = [num(x) for x in v]
            key = next((str(r[k]) for k in cfg.get("key", []) if r.get(k)), f"#{i}")
            if nums:
                out.append({"key": f"{Path(f).parent.name}/{key}"[:120], "numbers": dict(list(nums.items())[:30]), "tags": []})
    if not srcs:
        return {"state": "blocked", "entries": 0, "files": 0, "note": f"нет входа: {cfg.get('files')}"}
    return rows_to_records(ctx, cid, cfg, out, cfg["kind"], ",".join(srcs))


# ------------------------------------------------------------------ выбор типов из кода
def select_types(ctx: dict, sel: dict) -> list[tuple]:
    """-> [(Type, coverage_row)] по select: buckets/derives/name."""
    idx, cov = ctx["idx"], ctx["cov_by_type"]
    if idx is None:
        return []
    buckets = set(sel.get("buckets", []))
    der = sel.get("derives", [])
    nm = re.compile(sel["name"]) if sel.get("name") else None
    res = []
    for t in idx.types:
        r = cov.get(t.full)
        if r is None or r["bucket"] in ("lib", "debug", "art"):
            continue
        ok = r["bucket"] in buckets
        if not ok and der:
            ok = any(fnmatch.fnmatchcase(a, g) for a in t.ancestors for g in der)
        if not ok and nm:
            ok = bool(nm.search(t.name))
        if ok:
            res.append((t, r))
    res.sort(key=lambda x: (x[0].file, x[0].full))
    return res


def h_bucket_catalog(cid, cfg, ctx):
    sel = select_types(ctx, cfg.get("select", {}))
    if ctx["idx"] is None:
        return {"state": "blocked", "entries": 0, "files": 0, "note": "нет index.json / coverage.csv"}
    rows = []
    for t, r in sel:
        c = type_candidate(t, r)
        if c["_nums"]:
            rows.append({"key": f"{t.full} ({t.file})", "numbers": c["_nums"], "tags": [f"bucket={r['bucket']}"]})
    return rows_to_records(ctx, cid, cfg, rows, cid, "code_index")


def h_skeleton(cid, cfg, ctx):
    c = ctx["coll"][cid]
    sid = cfg["system"]
    sysd = ctx["tax"]["systems"][sid]
    chunk = cfg.get("chunk", ctx["defaults"]["skeleton_chunk"])
    sel = select_types(ctx, cfg.get("select", {})) if cfg.get("select") else []
    cands = []
    for t, r in sel:
        cd = type_candidate(t, r)
        cd.pop("_nums", None)
        cands.append(cd)
    template = {"id": f"C-{sid}-{cid}-000", "kind": cid, "own_name": "TODO: своё имя (скопируй строку на каждую запись)",
                "numbers": {re.sub(r"\(.*?\)", "", f).strip(): "TODO" for f in c.get("record_schema", [])
                            if isinstance(f, str)},
                "behavior": "TODO: поведение своими словами", "source_ref": "TODO"}
    parts = [cands[i:i + chunk] for i in range(0, len(cands), chunk)] or [[]]
    out_dir: Path = ctx["records_dir"] / "collections"
    names = set()
    for pi, part in enumerate(parts, 1):
        rec = {"schema": "reverse-kit-record/1", "game": ctx["game"], "status": "skeleton", "collection": cid,
               "system": {"id": sid, "slug": sysd["slug"], "title": sysd["title"]},
               "goal": f"TODO: «{c['title_ru']}» — что это даёт игроку и что изучаем",
               "rules": [], "catalog": [template] if pi == 1 else [], "open_questions": [], "acceptance": [],
               "meta": {"collection": cid, "title_ru": c["title_ru"], "definition_ru": c["definition_ru"],
                        "record_schema": c.get("record_schema", []), "extraction_source": c.get("extraction_source", []),
                        "cross_game_key": c.get("cross_game_key", ""), "priority": c.get("priority"),
                        "automation": c.get("automation"), "part": f"{pi}/{len(parts)}", "types": len(part),
                        "wol_examples": c.get("wol_examples", [])},
               "candidates": part}
        name = f"c-{cid}" + (f".part{pi:02d}" if len(parts) > 1 else "") + ".yaml"
        names.add(name)
        emit(out_dir, name, rec, HEADER_SKEL)
    for old in out_dir.glob(f"c-{cid}*.yaml"):   # лишние части (скелет уменьшился), только нетронутые
        if old.name not in names:
            st = json.loads((out_dir / ".gen_state.json").read_text(encoding="utf-8")) if (out_dir / ".gen_state.json").exists() else {}
            if st.get(old.name) == hashlib.sha1(old.read_bytes()).hexdigest():
                old.unlink()
    return {"state": "skeleton", "entries": len(cands), "files": len(parts),
            "note": f"{len(cands)} типов-кандидатов, {len(parts)} файл(ов)" if cands else "без кандидатов из кода (шаблон по схеме)"}


def h_todo(cid, cfg, ctx):
    c = ctx["coll"][cid]
    out = ctx["work_dir"] / "todo"
    out.mkdir(parents=True, exist_ok=True)
    lines = [f"# TODO: {c['title_ru']} (`{cid}`, {c['priority']}, manual)", "",
             f"Определение: {c['definition_ru']}", "", "## Схема записи", ""]
    lines += [f"- {f}" for f in c.get("record_schema", [])]
    lines += ["", "## Источники", "", "- " + ", ".join(c.get("extraction_source", []))]
    if c.get("needs_new_extraction"):
        lines += ["", f"Нужна новая выгрузка: {c.get('new_extraction_note', '')}"]
    lines += ["", "## Ключ сравнения между играми", "", c.get("cross_game_key", ""), "",
              "## Как делать", "",
              "1. Прочитать смежные спеки/коллекции и coverage-корзины игры.",
              "2. Писать запись `records/collections/c-" + cid + ".yaml` (schema.yaml, `collection: " + cid + "`), своими словами.",
              "3. Числа — в numbers с source_refs; сверить `verify_numbers.py`.", "",
              "## Пример (из игры №1)", ""] + [f"- {e}" for e in c.get("wol_examples", [])]
    p = out / f"{cid}.md"
    p.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return {"state": "todo", "entries": 0, "files": 1, "note": f"чек-лист {p.name}"}


def h_dir_inventory(cid, cfg, ctx):
    d = ctx["ref_dir"] / cfg["dir"]
    if not d.exists():
        return {"state": "blocked", "entries": 0, "files": 0, "note": f"нет {cfg['dir']}"}
    rows = []
    for sub in sorted(p for p in d.rglob("*") if p.is_dir()):
        files = [f for f in sub.iterdir() if f.is_file()]
        if not files:
            continue
        exts = {}
        for f in files:
            exts[f.suffix.lower() or "(none)"] = exts.get(f.suffix.lower() or "(none)", 0) + 1
        nums = {"files": len(files), "bytes": sum(f.stat().st_size for f in files)}
        nums.update({f"ext{e}": n for e, n in list(exts.items())[:6]})
        rows.append({"key": str(sub.relative_to(d)).replace("\\", "/"), "numbers": nums, "tags": []})
    return rows_to_records(ctx, cid, cfg, rows, "asset_dir", cfg["dir"])


HANDLERS = {"csv_rows": h_csv_rows, "json_tree": h_json_tree, "bucket_catalog": h_bucket_catalog,
            "skeleton": h_skeleton, "todo": h_todo, "dir_inventory": h_dir_inventory}


def pick_handler(cid: str, cfg: dict, automation: str) -> str:
    if cfg.get("handler"):
        return cfg["handler"]
    if automation in ("semi", "derived"):
        return "skeleton"
    if automation == "manual":
        return "todo"
    return "bucket_catalog" if cfg.get("select") else "todo"


def run_collection(cid: str, cfg: dict, ctx: dict) -> dict:
    cfg = dict(cfg)
    coll = ctx["coll"][cid]
    cfg.setdefault("system", ctx["defaults"]["family_system"][coll["family"]])
    h = pick_handler(cid, cfg, coll["automation"])
    try:
        res = HANDLERS[h](cid, cfg, ctx)
    except Exception as e:  # одна коллекция не роняет остальные
        res = {"state": "error", "entries": 0, "files": 0, "note": f"{e.__class__.__name__}: {e}"[:200]}
    res["handler"] = h
    return res

