"""C1: автоматическое отнесение каждого типа к системной корзине.

  python auto_coverage.py --index index.json --taxonomy taxonomy.yaml --out DIR
         [--override overrides/wol.yaml ...] [--hand hand_coverage.csv]

Слои (по убыванию надёжности):
  1. exact-переопределения игры (conf 1.0);
  2. правила таксономии: наследование (в т.ч. вложенные состояния), интерфейсы, namespace,
     путь/имя файла — побеждает правило с максимальным score;
  3. наследование корзины от ближайшего «своего» предка (не из generic_bases);
  4. корзина внешнего (вложенного-в) типа;
  5. близость по графу вызовов/ссылок: голосование уже размеченных соседей (с IDF-гашением хабов);
  остальное -> unassigned.
Выход: coverage.csv (type, base, bucket, confidence, reason, system, file, kind, parent),
coverage.md (сводка), и, если дан --hand, строка согласия в coverage.md + agreement.json.
"""
from __future__ import annotations
import argparse, csv, fnmatch, json, math, re, sys
from collections import Counter, defaultdict
from pathlib import Path

import yaml

sys.path.insert(0, str(Path(__file__).parent))
from index_io import Index, Type, load_index  # noqa: E402


def load_taxonomy(path: str, overrides: list[str]) -> dict:
    tax = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
    tax.setdefault("exact", {})
    tax.setdefault("eval_alias", {})
    for o in overrides or []:
        ov = yaml.safe_load(Path(o).read_text(encoding="utf-8")) or {}
        tax["exact"].update(ov.get("exact", {}))
        tax["eval_alias"].update(ov.get("eval_alias", {}))
        # правила игры идут впереди (при равном score побеждает первое)
        tax["rules"] = list(ov.get("rules", [])) + tax["rules"]
        tax["generic_bases"] = list(tax.get("generic_bases", [])) + list(ov.get("generic_bases", []))
        for k, v in (ov.get("buckets") or {}).items():
            tax["buckets"][k] = v
        for k, v in (ov.get("systems") or {}).items():
            tax["systems"][str(k)] = v
        if ov.get("thresholds"):
            tax["thresholds"].update(ov["thresholds"])
        tax.setdefault("overrides_used", []).append(str(o))
    return tax


def _g(pats, s: str) -> bool:
    return any(fnmatch.fnmatchcase(s, p) for p in pats)


class Rule:
    def __init__(self, r: dict, i: int):
        self.r, self.i = r, i
        self.bucket, self.conf = r["bucket"], float(r.get("conf", 0.7))
        self.name = re.compile(r["name"]) if r.get("name") else None
        self.path = re.compile(r["path"]) if r.get("path") else None

    def match(self, t: Type, idx: Index, encl: list[Type]) -> tuple[float, str] | None:

    def match(self, t: Type, idx: Index, encl: list[Type]) -> tuple[float, str] | None:
        r = self.r
        score_mul, why = 1.0, []
        if "kind" in r and t.kind not in r["kind"]:
            return None
        if r.get("top_level") and t.parent:
            return None
        if self.name is not None:
            if not self.name.search(t.name):
                return None
            why.append(f"name~{self.r['name'][:28]}")
        if self.path is not None:
            if not self.path.search(t.file):
                return None
            why.append("path")
        if "ns" in r:
            cand = [t.ns, t.file.rsplit("/", 1)[0].replace("/", ".") if "/" in t.file else ""]
            if not any(c and _g(r["ns"], c) for c in cand):
                return None
            why.append("ns")
        if "interface" in r:
            hit = [i for i in t.interfaces if _g(r["interface"], i.split(".")[-1].split("<")[0])]
            if not hit:
                return None
            why.append(f"iface {hit[0]}")
        if "direct" in r:
            if not (t.base and _g(r["direct"], t.simple(t.base))):
                return None
            why.append(f"base {t.simple(t.base)}")
        if "derives" in r:
            hit = next(((d, a) for d, a in enumerate(t.ancestors, 1) if _g(r["derives"], a)), None)
            if hit is None:
                return None
            score_mul *= max(0.75, 1 - 0.05 * (hit[0] - 1))
            why.append(f"derives {hit[1]}" + (f" (d{hit[0]})" if hit[0] > 1 else ""))
        if "nested_in" in r:
            h = next((e for e in encl if _g(r["nested_in"], e.name)), None)
            if h is None:
                return None
            why.append(f"nested in {h.name}")
        if "nested_derives" in r:
            if not any(_g(r["nested_derives"], a) for e in encl for a in e.ancestors):
                return None
            why.append("nested in derived")
        if not why and not any(k in r for k in ("kind", "top_level")):
            return None
        if "kind" in r and not why:
            why.append(f"kind {t.kind}")
        return self.conf * score_mul, "; ".join(why)


def classify(idx: Index, tax: dict) -> dict[str, dict]:
    th = tax["thresholds"]
    accept = th["accept"]
    rules = [Rule(r, i) for i, r in enumerate(tax["rules"])]
    generic = set(tax.get("generic_bases", []))
    exact = tax.get("exact", {})
    ignore_prox = set(th.get("proximity_ignore", []))
    res: dict[str, dict] = {}
    weak: dict[str, tuple] = {}

    def encl_of(t):
        return idx.enclosing(t)

    # --- слой 1-2: exact + правила
    for t in idx.types:
        hit = None
        for key in (t.full, t.name):
            for pat, b in exact.items():
                if fnmatch.fnmatchcase(key, pat):
                    hit = (b, 1.0, f"override {pat}")
                    break
            if hit:
                break
        if hit is None:
            enc = encl_of(t)
            best = None
            for rl in rules:
                m = rl.match(t, idx, enc)
                if m and (best is None or m[0] > best[0]):
                    best = (m[0], rl.bucket, m[1])
