import re
p='coverage/overrides/sns.yaml'
s=open(p,encoding='utf-8').read()
s=s.replace('(CharCols|CharRects|CharTrigEffects)','(CharCols|CharRects|CharTrig)')
open(p,'w',encoding='utf-8').write(s)

p='pipeline/extractors.py'
s=open(p,encoding='utf-8').read()
new='''def _flat_nums(r: dict, cfg: dict, skip=()) -> dict:
    """Числа записи: скаляры, bool -> 0/1, короткие числовые списки -> name_0.., списки объектов -> n_name."""
    nums = {}
    only = cfg.get("numbers")
    for k, v in r.items():
        if k in skip or (only and k not in only and not (isinstance(v, list) and k in cfg.get("list_fields", []))):
            continue
        if isinstance(v, bool):
            nums[k] = int(v)
        elif num(v) is not None and not isinstance(v, str):
            nums[k] = num(v)
        elif isinstance(v, list) and v and all(isinstance(x, (int, float)) and not isinstance(x, bool) for x in v) \\
                and len(v) <= cfg.get("list_max", 40):
            for i, x in enumerate(v):
                nums[f"{k}_{i}"] = num(x)
        elif isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
            nums[f"n_{k}"] = len(v)
    return nums


def h_json_nested(cid, cfg, ctx):
    """Вложенный JSON внешнего экспортёра (не-Unity игры): {группа: [объекты]} или [объекты].
    cfg: files, path (ключи до списка/словаря групп), group_keys, explode (поле-список объектов -> строка на элемент),
    parent_numbers, key, numbers (белый список), skip, tags (строковые поля <=40 симв. в теги), where, len_cols (длины строк
    вместо текста), kind. Строки-тексты (title/desc/text) НЕ копируются: только числа, bool и идентификаторы в tags/source_ref."""
    ref: Path = ctx["ref_dir"]
    out, srcs = [], []
    for f in cfg.get("files", []):
        p = ref / f
        if not p.exists():
            continue
        srcs.append(f)
        d = json.loads(p.read_text(encoding="utf-8-sig"))
        for k in cfg.get("path", []):
            d = d[k]
        groups = [(None, d)] if isinstance(d, list) else \\
            [(g, d[g]) for g in (cfg.get("group_keys") or list(d)) if isinstance(d.get(g), list)]
        for g, items in groups:
            for i, r in enumerate(items, 1):
                if not isinstance(r, dict):
                    continue
                if any(str(r.get(k, "")).lower() not in [str(x).lower() for x in v] for k, v in (cfg.get("where") or {}).items()):
                    continue
                base = " / ".join(str(r.get(k)) for k in cfg.get("key", []) if r.get(k) not in (None, "")) or f"#{i}"
                if g:
                    base = f"{g}/{base}"
                tags = ([f"group={g}"] if g else []) + [f"{k}={r[k]}" for k in cfg.get("tags", [])
                                                         if isinstance(r.get(k), str) and r[k] and len(r[k]) <= 40]
                skip = set(cfg.get("skip", [])) | set(cfg.get("key", [])) | set(cfg.get("tags", []))
                subs = [(None, r)]
                if cfg.get("explode"):
                    subs = [(j, e) for j, e in enumerate(r.get(cfg["explode"]) or []) if isinstance(e, dict)]
                for j, e in subs:
                    nums = {}
                    if j is not None:
                        nums.update({f"{k}": num(r[k]) for k in cfg.get("parent_numbers", []) if num(r.get(k)) is not None})
                        nums.update(_flat_nums(e, {}, ()))
                        nums["index"] = j
                        t2 = tags + [f"{k}={v}" for k, v in e.items() if isinstance(v, str) and v and len(v) <= 40]
                    else:
                        nums = _flat_nums(r, cfg, skip)
                        t2 = tags
                    if cfg.get("len_cols"):
                        for k, v in r.items():
                            if isinstance(v, list) and v and all(isinstance(x, str) for x in v):
                                nums[f"n_lang_{k}"] = len(v)
                                nums[f"len_{k}"] = len(v[0])
                            elif isinstance(v, str) and k in cfg.get("len_fields", []):
                                nums[f"len_{k}"] = len(v)
                    if nums:
                        out.append({"key": (base + (f" #{j}" if j is not None else ""))[:120],
                                    "numbers": dict(list(nums.items())[:cfg.get("max_numbers", 60)]), "tags": t2[:8]})
    if not srcs:
        return {"state": "blocked", "entries": 0, "files": 0, "note": f"нет входа: {cfg.get('files')} (запусти экспорт: --export-cmd)"}
    return rows_to_records(ctx, cid, cfg, out, cfg["kind"], ",".join(srcs))


'''
s=s.replace("# ------------------------------------------------------------------ выбор типов из кода", new+"# ------------------------------------------------------------------ выбор типов из кода",1)
s=s.replace('"json_tree": h_json_tree,','"json_tree": h_json_tree, "json_nested": h_json_nested,')
open(p,'w',encoding='utf-8').write(s)
E
