# Реестр коллекций под Salt and Sanctuary (игра №2, MonoGame). Формат — как collections_registry.yaml.
# Данные: ref_dir/data/*.json (выгрузка tools/export_data.py, строки-тексты НЕ копируются), код: coverage-корзины sns.yaml.
# Обработчик json_nested читает вложенный JSON: group_keys/explode/parent_numbers (см. pipeline/extractors.py).
# Когда появятся экспортёры map/dialog (другие помощники) — добавить файлы в room_templates / dialog_localization.
defaults:
  family_system: {feel_core: "01", anim_physics: "02", combat: "05", entities: "06", builds: "15",
                  numbers: "09", world: "07", presentation: "03", meta_tech: "29"}
  skeleton_chunk: 30
  csv_max_rows: 2000
  csv_rows_per_file: 400

collections:
  # --- A. feel_core
  locomotion_profiles: {handler: bucket_catalog, system: "01", select: {buckets: [player]}, chunk: 60}
  input_bindings:      {system: "26", select: {buckets: [input]}}
  attack_timelines:    {system: "02", select: {buckets: [combat]}}
  stat_pipelines:      {system: "14", select: {buckets: [stats, skills]}}
  fsm_catalogs:        {system: "00", select: {derives: [CharTrigActivator], name: '^Char(Update|Anim)'}}
  # --- B. anim_physics (данных анимации в выгрузке нет)
  anim_clips:          {handler: todo, system: "02"}
  anim_state_graphs:   {handler: todo, system: "02"}
  anim_event_timelines: {handler: todo, system: "02"}
  collision_geometry:  {handler: bucket_catalog, system: "02", select: {name: '^(CharCols|CharRects|HitBlock|Area)$'}}
  physics_setup:       {handler: bucket_catalog, system: "02", select: {name: 'Physics|Collision'}}
  # --- C. combat
  skill_records:       # узлы дерева навыков: стоимость, тип, значение, позиция, родители
    handler: json_nested
    system: "05"
    files: [data/skilltree.json]
    path: [classic]
    kind: skill_node
    key: [id, name]
    skip: [id, baseDesc, title, desc]
  arcana_catalog:      # магия (категория magic)
    handler: json_nested
    system: "05"
    files: [data/loot_classic.json]
    group_keys: [magic]
    kind: spell
    key: [name]
    skip: [texture]
  projectile_families: {system: "05", select: {name: '(Proj|Arrow|Missile|Bolt|Throw)'}}
  status_effects:      {system: "04", select: {name: '(Buff|Poison|Status|Curse|Bleed|Burn)'}}
  damage_rules:        {handler: todo, system: "02"}
  # --- D. entities
  enemy_roster:
    handler: json_nested
    system: "06"
    files: [data/monsters_classic.json]
    kind: enemy
    key: [name]
    numbers: [hp, attack, defense, poise, stamina, poiseAttack, blockReduce, blockDeflect, blockDmgReduce, blockMagReduce,
              runSpeed, fireDef, litDef, bladedDef, poisonDef, holyDef, darkDef, salt, boxWidth, boxHeight]
    tags: [def]
  enemy_ai_behaviors:
    handler: json_nested
    system: "06"
    files: [data/monsters_classic.json]
    kind: ai_params
    key: [name]
    numbers: [ai, type, flags, creature, attackReach, strongReach, specialReach, phaseThresh, crazeThresh, giant, hover,
              slowBack, bestiary, fadeLayer]
  boss_patterns:       {system: "10", select: {buckets: [boss], name: 'Boss'}}
  summons_allies:      {system: "21", select: {name: '(Summon|Ally|Beast|Pet)'}}
  # --- E. builds
  relic_catalog:       # экипировка и предметы: оружие/щиты/броня/кольца/расходники/материалы/ключи
    handler: json_nested
    system: "15"
    files: [data/loot_classic.json]
    group_keys: [weapon, shield, armor, ring, consumable, material, key]
    kind: equipment
    key: [name]
    skip: [img]
    tags: [texture]
  effect_templates:    {system: "15", select: {derives: [CharTrigActivator]}}
  item_synergies:      # рецепты улучшения: req x reqCount -> out за cost
    handler: json_nested
    system: "15"
    files: [data/loot_classic.json]
    kind: upgrade_recipe
    key: [name]
    explode: upgradePath
    parent_numbers: [category, upgrade, upgradeFac]
  build_archetypes:    {handler: todo, system: "16"}
  outfits:             {handler: bucket_catalog, system: "16", select: {buckets: [outfits]}}
  meta_unlocks:        # связи дерева навыков: узел -> родитель, стоимость узла
    handler: json_nested
    system: "12"
    files: [data/skilltree.json]
    path: [classic]
    kind: skill_edge
    key: [id, name]
    explode: parent
    skip_values: [-1]
    parent_numbers: [id, cost, type, value]
  # --- F. numbers
  value_curves:        {system: "14", select: {name: '(Curve|Ease|Lerp|Falloff|Decay|Damp)'}}
  currencies_prices:   # цена/вес/износ всех предметов
    handler: json_nested
    system: "09"
    files: [data/loot_classic.json]
    kind: price
    key: [name]
    numbers: [value, weight, durability, upgradeFac, upgrade]
  drop_tables:         # по строке на выпадение: шанс, число, соль монстра
    handler: json_nested
    system: "09"
    files: [data/monsters_classic.json]
    kind: drop
    key: [name]
    explode: drops
    parent_numbers: [salt]
  difficulty_adaptation: {system: "11", select: {name: '(Difficulty|Scaling|Adapt|NewGame|Plus)'}}
  run_flow_metrics:    {system: "11", select: {buckets: [run]}}
  # --- G. world
  room_templates:      {handler: bucket_catalog, system: "07", select: {buckets: [levelgen]}, chunk: 60}
  floor_generation_rules: {handler: todo, system: "07"}
  encounter_composition: {system: "08", select: {buckets: [encounter]}}
  special_rooms_services: {system: "18", select: {buckets: [hub_npc]}}
  props_hazards:       {handler: bucket_catalog, system: "20", select: {buckets: [props]}}
  tilesets_themes_decor: {system: "07", select: {buckets: [decor]}}
  run_structure:       {system: "11", select: {buckets: [run]}}
  level_design_patterns: {handler: todo, system: "07"}
  # --- H. presentation
  juice_feedback:      {system: "03", select: {buckets: [juice]}, chunk: 60}
  vfx_particles:       {system: "03", select: {name: '(Particle|Emitter|Burst|Trail|Smoke)'}}
  lighting_setups:     {system: "03", select: {name: '(Light(?!ning)|Glow|Shadow|Lamp|Torch|Tint|Refract)'}}
  camera_behaviors:    {handler: bucket_catalog, system: "23", select: {name: '(Camera|Scroll|Zoom|Shake|Quake)'}}
  audio_cues:          {system: "24", select: {buckets: [audio]}}
  audio_mix_rules:     {handler: todo, system: "24"}
  ui_surfaces:         {system: "25", select: {buckets: [ui, flow_ui]}, chunk: 60}
  art_asset_inventory: {handler: todo, system: "03"}
  feel_readability_clips: {handler: todo, system: "03"}
  # --- I. meta_tech
  dialog_localization: # строки интерфейса: число языков и длина английского (тексты не копируются)
    handler: json_nested
    system: "27"
    files: [data/strings.json]
    kind: ui_string
    key: [key]
    len_cols: true
  achievements_stats:  {handler: bucket_catalog, system: "28", select: {buckets: [achv]}}
  tutorial_onboarding: {system: "29", select: {name: '(Tutorial|Prompt|Guide|Hint)'}}
  persistence_settings: {system: "12", select: {buckets: [meta, input]}}
  multiplayer_modes:   {system: "13", select: {name: '(Coop|Online|Multi|Net|Leader)'}}
  code_architecture_patterns: {system: "00", select: {buckets: [engine]}, chunk: 60}

