cd "C:/visual projects/reverse-kit" && grep -n "def load_taxonomy" -A12 records/skeleton.py; grep -n "load_taxonomy\|overrid" records/skeleton.py | head; python - <<'E'
import csv
for r in csv.DictReader(open('pipeline/_work/run_sns/coverage/coverage.csv',encoding='utf-8')):
    if any(k in r['type'] for k in ('CharCols','CharRects','HitBlock','Physics','Collision','.Area','Col')) and r['bucket']!='ui': print(r['type'],r['bucket'])
E

